('1d0273fa-7027-55c6-a80e-79322b0f6fc8', 'd9fd4556-390d-533a-b9d4-f2885044e1b7', null, 'sample/d9fd4556-390d-533a-b9d4-f2885044e1b7/uploads/OAC_Meeting_15_DRAFT.pdf', 'OAC_Meeting_15_DRAFT.pdf', 'application/pdf', 'needs_review', null, 'OAC #15 (draft). CO-017 alternate: keep switchgear in room 104, extend feeders 240 LF — Bluebonnet pricing $131,900, 6 days. Owner leaning toward alternate. Curtain wall resubmittal received 10/8, Halvorsen reviewing. Lone Star COI still outstanding — Grace holding pay app #8. Next OAC 10/16.', '{"sample": true, "pages": 3}'::jsonb, (select id from _seed_owner), '2026-10-09 11:02-05'),
('8b03b178-c082-59b3-a274-c35e3dbf4fd6', 'd9fd4556-390d-533a-b9d4-f2885044e1b7', null, 'sample/d9fd4556-390d-533a-b9d4-f2885044e1b7/uploads/Balcones_Invoice_2219.pdf', 'Balcones_Invoice_2219.pdf', 'application/pdf', 'needs_review', null, 'Balcones Glass & Glazing. Invoice 2219. Stored materials — curtain wall extrusions (offsite, bonded warehouse). $214,600. Requires bill of sale and insurance certificate for offsite storage.', '{"sample": true, "pages": 1}'::jsonb, (select id from _seed_owner), '2026-10-08 11:02-05'),
