('18827d9a-bcce-58c2-96d4-921797d32a7b', 'a7a1dcea-796e-55cd-8c78-132fb38613be', null, 'sample/a7a1dcea-796e-55cd-8c78-132fb38613be/uploads/Northbrook_Addendum_01.pdf', 'Northbrook_Addendum_01.pdf', 'application/pdf', 'needs_review', null, 'Addendum 1. Bid date extended to Oct 22 at 2:00 PM. Roofing contractors must carry manufacturer-certified installer status for 20-year NDL warranty. Abatement removed from BP-1 scope.', '{"sample": true, "pages": 1}'::jsonb, (select id from _seed_owner), '2026-10-09 11:02-05'),
('962daa29-612b-5292-a413-58d0ef078d77', 'd9fd4556-390d-533a-b9d4-f2885044e1b7', 'e53d8045-194e-5f69-a785-1980a95f4c0d', 'sample/d9fd4556-390d-533a-b9d4-f2885044e1b7/uploads/RMOB_Schedule_Update_07.pdf', 'RMOB_Schedule_Update_07.pdf', 'application/pdf', 'complete', null, 'Schedule Update #7 narrative…', '{"sample": true}'::jsonb, (select id from _seed_owner), '2026-10-05 14:20-05');
